{
  "name": "FinMind AI",
  "description": "Your intelligent financial companion for smarter money decisions. Features AI-powered budgeting, receipt scanning, real-time financial advice, and goal visualization.",
  "requestFramePermissions": [
    "camera",
    "microphone",
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Page {
  DASHBOARD = 'DASHBOARD',
  TRANSACTIONS = 'TRANSACTIONS',
  CHAT = 'CHAT',
  LIVE_ADVISOR = 'LIVE_ADVISOR',
  GOALS = 'GOALS',
  MAPS = 'MAPS'
}

export interface Transaction {
  id: string;
  date: string;
  merchant: string;
  amount: number;
  category: string;
  isRecurring?: boolean;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
  images?: string[]; // base64
  groundingUrls?: Array<{title: string, uri: string}>;
}

export interface Goal {
  id: string;
  name: string;
  targetAmount: number;
  currentAmount: number;
  visualUrl?: string; // Generated image
  videoUrl?: string; // Generated video
}

import { GoogleGenAI, Type, FunctionDeclaration, Modality, LiveServerMessage } from "@google/genai";
import { Transaction } from "../types";

// NOTE: In a real app, strict environment variable usage is required.
// For this demo, we assume process.env.API_KEY is available.
const API_KEY = process.env.API_KEY || ''; 

const ai = new GoogleGenAI({ apiKey: API_KEY });

// --- 1. Chat Assistant (Text & Search) ---
export const createChatSession = () => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: "You are FinMind, an expert financial assistant. Help the user with budgeting, savings, and investment advice. Be concise and professional.",
      tools: [{ googleSearch: {} }]
    }
  });
};

// --- 2. Receipt Scanning (Vision) ---
export const analyzeReceipt = async (base64Data: string): Promise<Partial<Transaction> | null> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
          { text: "Analyze this receipt. Return a JSON object with 'merchant' (string), 'amount' (number), 'date' (YYYY-MM-DD), and 'category' (string). Only return the JSON." }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            merchant: { type: Type.STRING },
            amount: { type: Type.NUMBER },
            date: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ['merchant', 'amount', 'category']
        }
      }
    });

    const text = response.text;
    if (text) {
      return JSON.parse(text);
    }
    return null;
  } catch (e) {
    console.error("Receipt analysis failed", e);
    return null;
  }
};

// --- 3. Image Generation (Goals) ---
export const generateGoalImage = async (prompt: string): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9",
          imageSize: "2K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (e) {
    console.error("Image gen failed", e);
    return null;
  }
};

// --- 4. Video Generation (Veo) ---
export const generateMotivationVideo = async (prompt: string): Promise<string | null> => {
  try {
    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: prompt,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: '16:9'
      }
    });

    // Polling
    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 5000)); // Poll every 5s
      operation = await ai.operations.getVideosOperation({ operation: operation });
    }

    const uri = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (uri) {
      // In a real app, you would fetch this blob. For this demo we return the URI.
      // Note: This URI requires the API key appended to fetch.
      return `${uri}&key=${API_KEY}`;
    }
    return null;
  } catch (e) {
    console.error("Video gen failed", e);
    return null;
  }
};

// --- 5. Maps (Grounding) ---
export const findNearbyPlaces = async (query: string, lat: number, lng: number): Promise<Array<{title: string, uri: string}>> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: query,
      config: {
        tools: [{ googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: {
              latitude: lat,
              longitude: lng
            }
          }
        }
      },
    });

    // Extract grounding chunks
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const places = chunks
      .filter(c => c.web?.uri || c.entity?.webUri) // Adjust based on actual Maps chunk structure which often returns web-like grounding for places
      .map(c => ({
        title: c.web?.title || c.entity?.name || "Location",
        uri: c.web?.uri || c.entity?.webUri || "#"
      }));

    // If specific maps chunks are available (as per doc example), we use them. 
    // The doc says: groundingChunks.maps.uri
    const mapChunks = chunks.map((c: any) => {
        if (c.maps) return { title: c.maps.title, uri: c.maps.uri };
        return null;
    }).filter(Boolean);

    return mapChunks as Array<{title: string, uri: string}>;
  } catch (e) {
    console.error("Maps search failed", e);
    return [];
  }
};

// --- 6. TTS ---
export const speakText = async (text: string): Promise<AudioBuffer | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
       const binaryString = atob(base64Audio);
       const len = binaryString.length;
       const bytes = new Uint8Array(len);
       for (let i = 0; i < len; i++) {
         bytes[i] = binaryString.charCodeAt(i);
       }

       const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
       const audioBuffer = await audioContext.decodeAudioData(bytes.buffer);
       return audioBuffer;
    }
    return null;
  } catch (e) {
    console.error("TTS failed", e);
    return null;
  }
}

// --- 7. Live API Helper ---
export const getLiveClient = () => {
    return ai.live;
};

