import React, { useState, useEffect, useRef } from 'react';
import { ICONS } from '../constants';
import { ChatMessage } from '../types';
import { createChatSession, speakText } from '../services/geminiService';
import { GenerateContentResponse } from "@google/genai";

const ChatAssistant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: '1', role: 'model', text: "Hello! I'm FinMind. I can help you analyze your spending, find better savings rates, or answer financial questions.", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const chatSession = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatSession.current = createChatSession();
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || !chatSession.current) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const result: GenerateContentResponse = await chatSession.current.sendMessage({ message: userMsg.text });
      const responseText = result.text || "I couldn't generate a response.";

      // Check for grounding
      const groundingChunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
      const groundingUrls = groundingChunks?.map((c: any) => ({
         title: c.web?.title || 'Source',
         uri: c.web?.uri || '#'
      })).filter((x: any) => x.uri !== '#');

      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
        timestamp: new Date(),
        groundingUrls
      };

      setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Sorry, I encountered an error. Please check your API key.",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleTTS = async (text: string) => {
    const audioBuffer = await speakText(text);
    if (audioBuffer) {
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const source = audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContext.destination);
      source.start();
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-2rem)] bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
        <div>
           <h2 className="font-semibold text-slate-800">Financial Assistant</h2>
           <p className="text-xs text-slate-500">Powered by Gemini 3 Pro with Google Search</p>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/50">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-2xl p-4 ${
              msg.role === 'user' 
                ? 'bg-emerald-600 text-white rounded-tr-none' 
                : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none shadow-sm'
            }`}>
              <p className="whitespace-pre-wrap text-sm leading-relaxed">{msg.text}</p>

              {msg.groundingUrls && msg.groundingUrls.length > 0 && (
                <div className="mt-3 pt-3 border-t border-slate-100">
                  <p className="text-xs font-semibold text-slate-500 mb-1">Sources:</p>
                  <div className="flex flex-wrap gap-2">
                    {msg.groundingUrls.map((url, idx) => (
                      <a 
                        key={idx} 
                        href={url.uri} 
                        target="_blank" 
                        rel="noreferrer"
                        className="text-xs bg-slate-100 text-slate-600 px-2 py-1 rounded hover:bg-slate-200 truncate max-w-xs block"
                      >
                        {url.title}
                      </a>
                    ))}
                  </div>
                </div>
              )}

              {msg.role === 'model' && (
                <button 
                  onClick={() => handleTTS(msg.text)} 
                  className="mt-2 text-xs text-emerald-600 hover:text-emerald-700 font-medium flex items-center gap-1"
                >
                  <ICONS.Mic className="w-3 h-3" /> Listen
                </button>
              )}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-slate-100">
        <div className="flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask about stocks, budgets, or news..."
            className="flex-1 border border-slate-200 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-emerald-500 text-sm"
            disabled={isLoading}
          />
          <button
            onClick={handleSend}
            disabled={isLoading}
            className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg transition disabled:opacity-50"
          >
            {isLoading ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : <ICONS.Send className="w-5 h-5" />}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatAssistant;

import React, { useState, useEffect, useRef } from 'react';
import { ICONS } from '../constants';
import { getLiveClient } from '../services/geminiService';
import { LiveServerMessage, Modality } from '@google/genai';

const LiveAdvisor: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [status, setStatus] = useState('Disconnected');
  const [volume, setVolume] = useState(0); // For visualization

  const audioContextRef = useRef<AudioContext | null>(null);
  const inputSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const outputNodeRef = useRef<GainNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Initialization for audio contexts
  const initAudio = () => {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (!audioContextRef.current) {
        audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
        outputNodeRef.current = audioContextRef.current.createGain();
        outputNodeRef.current.connect(audioContextRef.current.destination);
    }
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const base64ToUint8Array = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

   const createBlob = (data: Float32Array) => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    // Simple encoding helper
    let binary = '';
    const bytes = new Uint8Array(int16.buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }

    return {
      data: btoa(binary),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  const connect = async () => {
    initAudio();
    setStatus('Connecting...');
    const liveClient = getLiveClient();

    try {
       // Input Audio Context (16kHz for input)
       const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 16000});
       const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

       sessionPromiseRef.current = liveClient.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus('Live & Listening');
            setIsConnected(true);

            // Setup Input Stream
            const source = inputCtx.createMediaStreamSource(stream);
            inputSourceRef.current = source;

            // ScriptProcessor for raw PCM access
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processorRef.current = processor;

            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              // Calculate volume for visualizer
              let sum = 0;
              for(let i=0; i<inputData.length; i++) sum += inputData[i]*inputData[i];
              setVolume(Math.sqrt(sum/inputData.length));

              const pcmBlob = createBlob(inputData);
              sessionPromiseRef.current?.then(session => {
                  session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
             const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
             if (base64Audio && audioContextRef.current && outputNodeRef.current) {
                const ctx = audioContextRef.current;
                const audioData = base64ToUint8Array(base64Audio);

                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

                const buffer = await decodeAudioData(audioData, ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(outputNodeRef.current);

                source.addEventListener('ended', () => {
                    sourcesRef.current.delete(source);
                });

                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buffer.duration;
                sourcesRef.current.add(source);
             }

             if (message.serverContent?.interrupted) {
                 sourcesRef.current.forEach(s => s.stop());
                 sourcesRef.current.clear();
                 nextStartTimeRef.current = 0;
             }
          },
          onclose: () => {
            setStatus('Disconnected');
            setIsConnected(false);
          },
          onerror: (err) => {
            console.error(err);
            setStatus('Error occurred');
            setIsConnected(false);
          }
        },
        config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
                voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } }
            },
            systemInstruction: "You are a friendly, empathetic financial advisor named Alex. Keep responses concise and conversational."
        }
      });

    } catch (e) {
      console.error(e);
      setStatus('Failed to connect');
    }
  };

  const disconnect = () => {
    if (processorRef.current) processorRef.current.disconnect();
    if (inputSourceRef.current) inputSourceRef.current.disconnect();
    if (sessionPromiseRef.current) {
        // There is no explicit close on the promise itself, but usually the client or session object has it.
        // We rely on breaking the stream.
        // session.close() if available.
        // Re-loading or unmounting is the cleanest cleanup for this demo structure.
    }
    setIsConnected(false);
    setStatus('Disconnected');
    setVolume(0);
    window.location.reload(); // Simple cleanup for demo to ensure audio context release
  };

  return (
    <div className="flex flex-col items-center justify-center h-full space-y-8 p-8 text-center bg-white rounded-xl shadow-sm border border-slate-100">
      <div className="space-y-4">
        <div className={`w-32 h-32 rounded-full flex items-center justify-center transition-all duration-100 ${isConnected ? 'bg-emerald-100' : 'bg-slate-100'}`}
             style={{ transform: `scale(${1 + volume * 2})` }}>
          <div className={`w-24 h-24 rounded-full flex items-center justify-center ${isConnected ? 'bg-emerald-500 text-white shadow-emerald-500/50 shadow-lg' : 'bg-slate-300 text-slate-500'}`}>
            {isConnected ? <ICONS.Mic className="w-10 h-10" /> : <ICONS.MicOff className="w-10 h-10" />}
          </div>
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Live Financial Advisor</h2>
          <p className="text-slate-500">{status}</p>
        </div>
      </div>

      <button
        onClick={isConnected ? disconnect : connect}
        className={`px-8 py-4 rounded-full font-bold text-lg transition-all ${
            isConnected 
            ? 'bg-red-50 text-red-600 hover:bg-red-100' 
            : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-xl shadow-emerald-500/20'
        }`}
      >
        {isConnected ? 'End Conversation' : 'Start Conversation'}
      </button>

      <p className="text-sm text-slate-400 max-w-md">
        Experience real-time, low-latency voice conversations powered by Gemini Live. Ask about your portfolio, market trends, or just vent about inflation.
      </p>
    </div>
  );
};

export default LiveAdvisor;

import React, { useState } from 'react';
import { analyzeReceipt } from '../services/geminiService';
import { Transaction } from '../types';
import { ICONS } from '../constants';

const ReceiptScanner: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<Partial<Transaction> | null>(null);
  const [preview, setPreview] = useState<string | null>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setAnalyzing(true);
    setResult(null);

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setPreview(base64);
      // Remove data URL prefix for API
      const base64Data = base64.split(',')[1];

      const data = await analyzeReceipt(base64Data);
      setResult(data);
      setAnalyzing(false);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 max-w-2xl mx-auto">
      <h2 className="text-xl font-bold text-slate-800 mb-4">Receipt Scanner</h2>
