import React, { useState, useRef } from 'react';
import { ICONS } from '../constants';
import { getLiveClient } from '../services/geminiService';
import { LiveServerMessage, Modality } from '@google/genai';

const LiveAdvisor: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [status, setStatus] = useState('Ready to Connect');
  const [volume, setVolume] = useState(0); 

  const audioContextRef = useRef<AudioContext | null>(null);
  const inputSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const outputNodeRef = useRef<GainNode | null>(null);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // ... (Audio processing logic remains same as provided previously, just wrapped in new UI) ...
  const initAudio = () => {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (!audioContextRef.current) {
        audioContextRef.current = new AudioContextClass({ sampleRate: 24000 });
        outputNodeRef.current = audioContextRef.current.createGain();
        outputNodeRef.current.connect(audioContextRef.current.destination);
    }
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const createBlob = (data: Float32Array) => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) { int16[i] = data[i] * 32768; }
    let binary = '';
    const bytes = new Uint8Array(int16.buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) { binary += String.fromCharCode(bytes[i]); }
    return { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' };
  };

  const connect = async () => {
    initAudio();
    setStatus('Initializing secure link...');
    const liveClient = getLiveClient();
    try {
       const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 16000});
       const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
       sessionPromiseRef.current = liveClient.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus('Listening...');
            setIsConnected(true);
            const source = inputCtx.createMediaStreamSource(stream);
            inputSourceRef.current = source;
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processorRef.current = processor;
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              let sum = 0;
              for(let i=0; i<inputData.length; i++) sum += inputData[i]*inputData[i];
              setVolume(Math.sqrt(sum/inputData.length));
              const pcmBlob = createBlob(inputData);
              sessionPromiseRef.current?.then(session => { session.sendRealtimeInput({ media: pcmBlob }); });
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
             const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
             if (base64Audio && audioContextRef.current && outputNodeRef.current) {
                const ctx = audioContextRef.current;
                const binaryString = atob(base64Audio);
                const bytes = new Uint8Array(binaryString.length);
                for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
                const buffer = await decodeAudioData(bytes, ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(outputNodeRef.current);
                source.addEventListener('ended', () => { sourcesRef.current.delete(source); });
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buffer.duration;
                sourcesRef.current.add(source);
             }
             if (message.serverContent?.interrupted) {
                 sourcesRef.current.forEach(s => s.stop());
                 sourcesRef.current.clear();
                 nextStartTimeRef.current = 0;
             }
          },
          onclose: () => { setStatus('Session Ended'); setIsConnected(false); },
          onerror: (err) => { console.error(err); setStatus('Connection Error'); setIsConnected(false); }
        },
        config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
            systemInstruction: "You are FinMind, a highly intelligent and sophisticated financial advisor. Speak concisely."
        }
      });
    } catch (e) { console.error(e); setStatus('Connection Failed'); }
  };

  const disconnect = () => {
    if (processorRef.current) processorRef.current.disconnect();
    if (inputSourceRef.current) inputSourceRef.current.disconnect();
    setIsConnected(false);
    setStatus('Disconnected');
    setVolume(0);
    window.location.reload(); 
  };

  return (
    <div className="flex flex-col h-full bg-black rounded-[40px] relative overflow-hidden text-white shadow-2xl">
      {/* Background gradients */}
      <div className="absolute inset-0 bg-gradient-to-b from-[#1c1c1e] to-black z-0"></div>
      <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-accent/20 rounded-full blur-[100px] transition-all duration-700 ease-in-out ${isConnected ? 'opacity-100 scale-110' : 'opacity-20 scale-90'}`}></div>

      <div className="relative z-10 flex flex-col h-full items-center justify-center p-8">
        {/* Visualizer Orb */}
        <div className="relative mb-12">
            <div 
              className={`w-40 h-40 rounded-full bg-gradient-to-tr from-blue-500 via-accent to-purple-500 blur-md transition-all duration-100 ${isConnected ? 'animate-pulse-slow' : 'opacity-50 grayscale'}`}
              style={{ transform: `scale(${1 + volume * 3})` }}
            ></div>
            <div className="absolute inset-0 flex items-center justify-center">
                 {isConnected ? (
                     <div className="w-36 h-36 rounded-full bg-black/50 backdrop-blur-md flex items-center justify-center border border-white/10">
                         <ICONS.Mic className="w-10 h-10 text-white" />
                     </div>
                 ) : (
                     <div className="w-36 h-36 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center border border-white/5">
                         <ICONS.MicOff className="w-10 h-10 text-white/50" />
                     </div>
                 )}
            </div>
        </div>

        <h2 className="text-3xl font-bold tracking-tight mb-2 text-center">
            {isConnected ? "I'm listening..." : "Live Financial Advisor"}
        </h2>
        <p className={`text-center max-w-md transition-colors duration-300 ${isConnected ? 'text-accent' : 'text-gray-400'}`}>
            {status}
        </p>

        <div className="mt-16">
            <button
                onClick={isConnected ? disconnect : connect}
                className={`group relative px-8 py-4 rounded-full font-semibold text-lg transition-all duration-300 ${
                    isConnected 
                    ? 'bg-red-500/10 text-red-500 border border-red-500/50 hover:bg-red-500 hover:text-white' 
                    : 'bg-white text-black hover:scale-105 shadow-[0_0_30px_rgba(255,255,255,0.3)]'
                }`}
            >
                {isConnected ? 'End Session' : 'Start Conversation'}
            </button>
        </div>
      </div>

      {/* Bottom Hint */}
      <div className="absolute bottom-8 w-full text-center z-10">
         <p className="text-white/20 text-xs font-medium uppercase tracking-widest">Powered by Gemini Live</p>
      </div>
    </div>
  );
};

export default LiveAdvisor;

import React, { useState, useEffect, useRef } from 'react';
import { ICONS } from '../constants';
import { ChatMessage } from '../types';
import { createChatSession, speakText } from '../services/geminiService';
import { GenerateContentResponse } from "@google/genai";

const ChatAssistant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: '1', role: 'model', text: "Hello! I'm FinMind. Ask me anything about your finances.", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const chatSession = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatSession.current = createChatSession();
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || !chatSession.current) return;
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const result: GenerateContentResponse = await chatSession.current.sendMessage({ message: userMsg.text });
      const responseText = result.text || "I couldn't generate a response.";
      const groundingChunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
      const groundingUrls = groundingChunks?.map((c: any) => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '#' })).filter((x: any) => x.uri !== '#');

      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
        timestamp: new Date(),
        groundingUrls
      };
      setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: "Error connecting to AI.", timestamp: new Date() }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-[32px] shadow-soft overflow-hidden border border-white/50">
      {/* Header */}
      <div className="p-6 border-b border-gray-100 bg-white/80 backdrop-blur-md flex justify-between items-center z-10 sticky top-0">
        <div className="flex items-center gap-3">
           <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-accent to-blue-500 p-0.5">
             <div className="w-full h-full bg-white rounded-full flex items-center justify-center">
                <ICONS.Chat className="w-5 h-5 text-accent" />
             </div>
           </div>
           <div>
              <h2 className="font-bold text-primary">FinMind Assistant</h2>
              <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                <p className="text-xs text-secondary font-medium">Online</p>
              </div>
           </div>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-gray-50/50">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[75%] rounded-[24px] px-6 py-4 shadow-sm relative ${
              msg.role === 'user' 
                ? 'bg-primary text-white rounded-br-none' 
                : 'bg-white text-primary border border-gray-100 rounded-bl-none'
            }`}>
              <p className="whitespace-pre-wrap text-sm leading-relaxed font-medium">{msg.text}</p>

              {msg.groundingUrls && msg.groundingUrls.length > 0 && (
                <div className="mt-3 pt-3 border-t border-gray-100/20">
                  <div className="flex flex-wrap gap-2">
                    {msg.groundingUrls.map((url, idx) => (
                      <a key={idx} href={url.uri} target="_blank" rel="noreferrer"
                        className="text-[10px] bg-black/5 text-primary/70 px-2 py-1 rounded-md hover:bg-black/10 transition block truncate max-w-xs font-semibold">
                        {url.title} ↗
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-white px-5 py-4 rounded-[24px] rounded-bl-none border border-gray-100 shadow-sm flex gap-1">
                    <span className="w-2 h-2 bg-gray-300 rounded-full animate-bounce"></span>
                    <span className="w-2 h-2 bg-gray-300 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></span>
                    <span className="w-2 h-2 bg-gray-300 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></span>
                </div>
            </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-6 bg-white border-t border-gray-100">
        <div className="relative">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type a message..."
            className="w-full bg-gray-100 text-primary placeholder-gray-400 rounded-full px-6 py-4 pr-14 focus:outline-none focus:ring-2 focus:ring-primary/10 font-medium transition-all hover:bg-gray-50 border border-transparent hover:border-gray-200"
            disabled={isLoading}
          />
          <button
            onClick={handleSend}
            disabled={isLoading || !input.trim()}
            className="absolute right-2 top-2 w-10 h-10 bg-primary rounded-full flex items-center justify-center text-white hover:bg-black transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <ICONS.Send className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatAssistant;

import React, { useState } from 'react';
import { analyzeReceipt } from '../services/geminiService';
import { Transaction } from '../types';
import { ICONS } from '../constants';

const ReceiptScanner: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<Partial<Transaction> | null>(null);
  const [preview, setPreview] = useState<string | null>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setAnalyzing(true);
    setResult(null);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setPreview(base64);
      const base64Data = base64.split(',')[1];
      const data = await analyzeReceipt(base64Data);
      setResult(data);
      setAnalyzing(false);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pt-4">
      <div className="text-center space-y-2">
          <h2 className="text-3xl font-bold text-primary">Smart Scanner</h2>
          <p className="text-secondary">Digitize your receipts instantly using Gemini Vision.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Upload Area */}
          <div className="group relative w-full aspect-[4/5] md:aspect-square bg-white rounded-[32px] border-2 border-dashed border-gray-200 hover:border-accent hover:bg-accent/5 transition-all duration-300 flex flex-col items-center justify-center cursor-pointer overflow-hidden shadow-sm">
             <input type="file" accept="image/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />

             {preview ? (
                 <img src={preview} alt="Receipt" className="absolute inset-0 w-full h-full object-cover" />
             ) : (
                 <div className="text-center p-8 transition-transform group-hover:scale-105 duration-300">
                     <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:bg-white group-hover:shadow-lg">
                         <ICONS.Receipt className="w-8 h-8 text-secondary group-hover:text-accent" />
                     </div>
                     <p className="font-bold text-primary">Tap to Upload</p>
                     <p className="text-sm text-secondary mt-1">or drag and drop here</p>
                 </div>
             )}

             {analyzing && (
                 <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-30 flex flex-col items-center justify-center">
                     <div className="w-12 h-12 border-4 border-accent border-t-transparent rounded-full animate-spin mb-4"></div>
                     <p className="font-bold text-primary animate-pulse">Extracting Data...</p>
                 </div>
             )}
          </div>

          {/* Results Area */}
          <div className="flex flex-col h-full">
            {result ? (
                <div className="glass-card p-8 rounded-[32px] h-full flex flex-col justify-center animate-float">
                    <div className="w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6">
                        <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                    </div>
                    <h3 className="text-2xl font-bold text-primary mb-6">Receipt Analyzed</h3>

                    <div className="space-y-6">
                        <div className="flex justify-between items-center py-2 border-b border-gray-100">
                            <span className="text-secondary text-sm font-medium">Merchant</span>
                            <span className="text-lg font-bold text-primary">{result.merchant}</span>
                        </div>
                        <div className="flex justify-between items-center py-2 border-b border-gray-100">
                            <span className="text-secondary text-sm font-medium">Amount</span>
                            <span className="text-2xl font-bold text-primary">${result.amount}</span>
                        </div>
                        <div className="flex justify-between items-center py-2 border-b border-gray-100">
                            <span className="text-secondary text-sm font-medium">Date</span>
                            <span className="text-primary font-medium">{result.date}</span>
                        </div>
                        <div className="flex justify-between items-center py-2">
                            <span className="text-secondary text-sm font-medium">Category</span>
                            <span className="px-3 py-1 bg-accent/10 text-accent rounded-full text-sm font-bold">{result.category}</span>
                        </div>
                    </div>

                    <button className="mt-8 w-full bg-primary text-white py-4 rounded-xl font-bold hover:bg-black transition-all shadow-lg shadow-primary/20">
                        Save to Dashboard
                    </button>
                </div>
            ) : (
                <div className="h-full rounded-[32px] border border-gray-200 bg-gray-50 flex items-center justify-center p-8 text-center">
                    <p className="text-secondary font-medium">Upload a receipt to see the magic happen.</p>
                </div>
            )}
          </div>
      </div>
    </div>
  );
};

export default ReceiptScanner;

import React, { useState } from 'react';
import { generateGoalImage, generateMotivationVideo } from '../services/geminiService';

const GoalVisualizer: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [mediaType, setMediaType] = useState<'IMAGE' | 'VIDEO'>('IMAGE');
  const [loading, setLoading] = useState(false);
  const [resultUrl, setResultUrl] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setResultUrl(null);
    if (mediaType === 'IMAGE') {
        const url = await generateGoalImage(prompt);
        setResultUrl(url);
    } else {
        const url = await generateMotivationVideo(prompt);
        setResultUrl(url);
    }
    setLoading(false);
  };

  return (
    <div className="h-full flex flex-col space-y-6 pt-4">
      <div className="flex justify-between items-end">
          <div>
            <h2 className="text-3xl font-bold text-primary">Goal Vision Board</h2>
            <p className="text-secondary mt-1">Manifest your dreams with AI.</p>
          </div>
          <div className="bg-white p-1 rounded-xl shadow-sm border border-gray-100 flex">
              <button 
                onClick={() => setMediaType('IMAGE')}
                className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${mediaType === 'IMAGE' ? 'bg-primary text-white shadow-md' : 'text-secondary hover:bg-gray-50'}`}
              >
                  Image
              </button>
              <button 
                onClick={() => setMediaType('VIDEO')}
                className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${mediaType === 'VIDEO' ? 'bg-primary text-white shadow-md' : 'text-secondary hover:bg-gray-50'}`}
              >
                  Video
              </button>
          </div>
      </div>

      <div className="glass-card p-2 rounded-[24px] flex items-center shadow-sm">
          <input 
            type="text" 
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder={mediaType === 'IMAGE' ? "Ex: A modern cabin in Swiss Alps..." : "Ex: Cinematic drone shot of a luxury yacht..."}
            className="flex-1 bg-transparent border-none focus:ring-0 px-6 py-4 text-primary placeholder-gray-400 font-medium"
          />
          <button 
            onClick={handleGenerate}
            disabled={loading || !prompt}
            className="bg-accent hover:bg-accent-hover text-white px-8 py-3 rounded-[20px] font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed m-1 shadow-lg shadow-accent/20"
          >
            {loading ? 'Dreaming...' : 'Visualize'}
          </button>
      </div>

      <div className="flex-1 rounded-[32px] overflow-hidden bg-white border border-gray-200 relative group shadow-inner">
          {loading && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-white z-10">
                 <div className="w-16 h-16 border-4 border-accent border-t-transparent rounded-full animate-spin mb-4"></div>
                 <p className="text-primary font-bold animate-pulse">Constructing Reality...</p>
             </div>
          )}

          {!loading && !resultUrl && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-8 opacity-40">
                  <div className="text-6xl mb-4">✨</div>
                  <h3 className="text-2xl font-bold text-primary">Your Canvas is Empty</h3>
                  <p className="text-secondary">Type a dream above to see it come to life.</p>
              </div>
          )}

          {!loading && resultUrl && (
              <div className="w-full h-full p-4">
                  {mediaType === 'IMAGE' ? (
                      <img src={resultUrl} alt="Generated Goal" className="w-full h-full object-cover rounded-[24px] shadow-2xl transition-transform duration-700 hover:scale-[1.02]" />
                  ) : (
                      <video controls autoPlay loop className="w-full h-full object-cover rounded-[24px] shadow-2xl">
                          <source src={resultUrl} type="video/mp4" />
                      </video>
                  )}
              </div>
          )}
      </div>
    </div>
  );
};

export default GoalVisualizer;

