const GoalVisualizer: React.FC = () => {
  const { goals, addGoal, deleteGoal } = useFinMind();
  const [prompt, setPrompt] = useState('');
  const [mediaType, setMediaType] = useState<'IMAGE' | 'VIDEO'>('IMAGE');
  const [loading, setLoading] = useState(false);
  const [currentResult, setCurrentResult] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setCurrentResult(null);
    let url: string | null = null;

    if (mediaType === 'IMAGE') {
        url = await generateGoalImage(prompt);
    } else {
        url = await generateMotivationVideo(prompt);
    }

    if (url) {
        setCurrentResult(url);
    }
    setLoading(false);
  };

  const handleSave = () => {
      if (currentResult && prompt) {
          addGoal({
              title: prompt,
              visualUrl: currentResult,
              type: mediaType
          });
          setPrompt('');
          setCurrentResult(null);
      }
  };

  return (
    <div className="h-full flex flex-col space-y-8 pt-4">
      <div className="flex justify-between items-end">
          <div>
            <h2 className="text-3xl font-bold text-primary">Vision Board</h2>
