import React, { createContext, useContext, useState, useEffect } from 'react';
import { Transaction, Goal, AppState } from '../types';

interface FinMindContextType extends AppState {
  addTransaction: (t: Omit<Transaction, 'id' | 'status'>) => void;
  deleteTransaction: (id: string) => void;
  addGoal: (g: Omit<Goal, 'id' | 'createdAt'>) => void;
  deleteGoal: (id: string) => void;
  addToWatchlist: (ticker: string) => void;
  removeFromWatchlist: (ticker: string) => void;
}

const FinMindContext = createContext<FinMindContextType | undefined>(undefined);

const INITIAL_DATA: Transaction[] = [
  { id: '1', date: '2023-10-24', merchant: 'Apple Store', amount: 1200, category: 'Tech', status: 'completed' },
  { id: '2', date: '2023-10-23', merchant: 'Whole Foods', amount: 142.50, category: 'Groceries', status: 'completed' },
  { id: '3', date: '2023-10-22', merchant: 'Uber', amount: 24.00, category: 'Transport', status: 'completed' },
  { id: '4', date: '2023-10-21', merchant: 'Netflix', amount: 15.99, category: 'Subscription', isRecurring: true, status: 'completed' },
  { id: '5', date: '2023-10-20', merchant: 'Starbucks', amount: 8.50, category: 'Food', status: 'completed' },
];

export const FinMindProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Load from local storage or use initial mock data
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finmind_transactions');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('finmind_goals');
    return saved ? JSON.parse(saved) : [];
  });

  const [watchlist, setWatchlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('finmind_watchlist');
    return saved ? JSON.parse(saved) : ['AAPL', 'GOOGL', 'BTC', 'ETH'];
  });

  const [user] = useState({
    name: 'Alex Doe',
    monthlyBudget: 3000
  });

  // Persist to local storage
  useEffect(() => {
    localStorage.setItem('finmind_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('finmind_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('finmind_watchlist', JSON.stringify(watchlist));
  }, [watchlist]);

  const addTransaction = (t: Omit<Transaction, 'id' | 'status'>) => {
    const newTransaction: Transaction = {
      ...t,
      id: Date.now().toString(),
      status: 'completed'
    };
    setTransactions(prev => [newTransaction, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const addGoal = (g: Omit<Goal, 'id' | 'createdAt'>) => {
    const newGoal: Goal = {
      ...g,
      id: Date.now().toString(),
      createdAt: new Date()
    };
    setGoals(prev => [newGoal, ...prev]);
  };

  const deleteGoal = (id: string) => {
    setGoals(prev => prev.filter(g => g.id !== id));
  };

  const addToWatchlist = (ticker: string) => {
    if (!watchlist.includes(ticker)) {
      setWatchlist(prev => [...prev, ticker]);
    }
  };

  const removeFromWatchlist = (ticker: string) => {
    setWatchlist(prev => prev.filter(t => t !== ticker));
  };

  return (
    <FinMindContext.Provider value={{ transactions, goals, user, watchlist, addTransaction, deleteTransaction, addGoal, deleteGoal, addToWatchlist, removeFromWatchlist }}>
      {children}
    </FinMindContext.Provider>
  );
};

export const useFinMind = () => {
  const context = useContext(FinMindContext);
  if (!context) {
    throw new Error('useFinMind must be used within a FinMindProvider');
  }
  return context;
};

