      </div>
    </div>
  );
};

export default Markets;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Transaction, Goal, AppState } from '../types';

interface FinMindContextType extends AppState {
  addTransaction: (t: Omit<Transaction, 'id' | 'status'>) => void;
  updateTransaction: (id: string, updates: Partial<Transaction>) => void;
  deleteTransaction: (id: string) => void;
  addGoal: (g: Omit<Goal, 'id' | 'createdAt'>) => void;
  deleteGoal: (id: string) => void;
  addToWatchlist: (ticker: string) => void;
  removeFromWatchlist: (ticker: string) => void;
}

const FinMindContext = createContext<FinMindContextType | undefined>(undefined);

const INITIAL_DATA: Transaction[] = [
  { id: '1', date: '2023-10-24', merchant: 'Apple Store', amount: 1200, category: 'Tech', status: 'completed' },
  { id: '2', date: '2023-10-23', merchant: 'Whole Foods', amount: 142.50, category: 'Groceries', status: 'completed' },
  { id: '3', date: '2023-10-22', merchant: 'Uber', amount: 24.00, category: 'Transport', status: 'completed' },
  { id: '4', date: '2023-10-21', merchant: 'Netflix', amount: 15.99, category: 'Subscription', isRecurring: true, status: 'completed' },
  { id: '5', date: '2023-10-20', merchant: 'Starbucks', amount: 8.50, category: 'Food', status: 'completed' },
];

export const FinMindProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Load from local storage or use initial mock data
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finmind_transactions');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [goals, setGoals] = useState<Goal[]>(() => {
    const saved = localStorage.getItem('finmind_goals');
    return saved ? JSON.parse(saved) : [];
  });

  const [watchlist, setWatchlist] = useState<string[]>(() => {
    const saved = localStorage.getItem('finmind_watchlist');
    return saved ? JSON.parse(saved) : ['AAPL', 'GOOGL', 'BTC', 'ETH'];
  });

  const [user] = useState({
    name: 'Alex Doe',
    monthlyBudget: 3000
  });

  // Persist to local storage
  useEffect(() => {
    localStorage.setItem('finmind_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('finmind_goals', JSON.stringify(goals));
  }, [goals]);

  useEffect(() => {
    localStorage.setItem('finmind_watchlist', JSON.stringify(watchlist));
  }, [watchlist]);

  const addTransaction = (t: Omit<Transaction, 'id' | 'status'>) => {
    const newTransaction: Transaction = {
      ...t,
      id: Date.now().toString(),
      status: 'completed'
    };
    setTransactions(prev => [newTransaction, ...prev]);
  };

  const updateTransaction = (id: string, updates: Partial<Transaction>) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const addGoal = (g: Omit<Goal, 'id' | 'createdAt'>) => {
    const newGoal: Goal = {
      ...g,
      id: Date.now().toString(),
      createdAt: new Date()
    };
    setGoals(prev => [newGoal, ...prev]);
  };

  const deleteGoal = (id: string) => {
    setGoals(prev => prev.filter(g => g.id !== id));
  };

  const addToWatchlist = (ticker: string) => {
    if (!watchlist.includes(ticker)) {
      setWatchlist(prev => [...prev, ticker]);
    }
  };

  const removeFromWatchlist = (ticker: string) => {
    setWatchlist(prev => prev.filter(t => t !== ticker));
  };

  return (
    <FinMindContext.Provider value={{ transactions, goals, user, watchlist, addTransaction, updateTransaction, deleteTransaction, addGoal, deleteGoal, addToWatchlist, removeFromWatchlist }}>
      {children}
    </FinMindContext.Provider>
  );
};

export const useFinMind = () => {
  const context = useContext(FinMindContext);
  if (!context) {
    throw new Error('useFinMind must be used within a FinMindProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { Transaction } from '../types';

interface TransactionModalProps {
  transaction: Transaction;
  onClose: () => void;
  onSave: (id: string, updates: Partial<Transaction>) => void;
  onDelete: (id: string) => void;
}

const TransactionModal: React.FC<TransactionModalProps> = ({ transaction, onClose, onSave, onDelete }) => {
  const [formData, setFormData] = useState(transaction);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'amount' ? parseFloat(value) : value
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(transaction.id, formData);
    onClose();
  };

  const handleDelete = () => {
    onDelete(transaction.id);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-md animate-enter" onClick={onClose}>
      <div 
        className="bg-white rounded-[32px] p-8 w-full max-w-md shadow-2xl scale-100 transition-transform"
        onClick={e => e.stopPropagation()}
      >
         <div className="flex justify-between items-center mb-6">
             <h3 className="text-2xl font-bold text-primary">Edit Transaction</h3>
             <button onClick={onClose} className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center text-secondary hover:bg-gray-200 transition-colors">
                 <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
             </button>
         </div>

         <form onSubmit={handleSubmit} className="space-y-5">
             <div>
                 <label className="block text-xs font-bold text-secondary uppercase tracking-wider mb-2">Merchant</label>
                 <input 
                    type="text" 
                    name="merchant"
                    value={formData.merchant}
                    onChange={handleChange}
                    className="w-full bg-gray-50 border-none rounded-xl px-4 py-3 font-bold text-primary focus:ring-2 focus:ring-accent"
                 />
             </div>

             <div className="flex gap-4">
                 <div className="flex-1">
                     <label className="block text-xs font-bold text-secondary uppercase tracking-wider mb-2">Amount ($)</label>
                     <input 
                        type="number" 
                        name="amount"
                        step="0.01"
                        value={formData.amount}
                        onChange={handleChange}
                        className="w-full bg-gray-50 border-none rounded-xl px-4 py-3 font-bold text-primary focus:ring-2 focus:ring-accent"
                     />
                 </div>
                 <div className="flex-1">
                     <label className="block text-xs font-bold text-secondary uppercase tracking-wider mb-2">Date</label>
                     <input 
                        type="date" 
                        name="date"
                        value={formData.date}
                        onChange={handleChange}
                        className="w-full bg-gray-50 border-none rounded-xl px-4 py-3 font-medium text-primary focus:ring-2 focus:ring-accent"
                     />
                 </div>
             </div>

             <div>
                 <label className="block text-xs font-bold text-secondary uppercase tracking-wider mb-2">Category</label>
                 <input 
                    type="text" 
                    name="category"
                    value={formData.category}
                    onChange={handleChange}
                    className="w-full bg-gray-50 border-none rounded-xl px-4 py-3 font-medium text-primary focus:ring-2 focus:ring-accent"
                 />
             </div>

             <div className="pt-4 flex gap-3">
                 <button 
                    type="button" 
                    onClick={handleDelete}
                    className="flex-1 bg-red-50 text-red-500 py-3.5 rounded-xl font-bold hover:bg-red-100 transition-colors"
                 >
                    Delete
                 </button>
                 <button 
                    type="submit" 
                    className="flex-[2] bg-primary text-white py-3.5 rounded-xl font-bold hover:bg-black transition-all shadow-lg shadow-primary/20"
                 >
                    Save Changes
                 </button>
             </div>
         </form>
      </div>
    </div>
  );
};

export default TransactionModal;

import React, { useState } from 'react';
import { useFinMind } from '../context/FinMindContext';
import ReceiptScanner from './ReceiptScanner';
