      {/* Transactions List */}
      <div className="flex-1 glass-card rounded-[32px] overflow-hidden flex flex-col border border-white/60">
        <div className="p-6 border-b border-gray-100 flex gap-4">
             <div className="relative flex-1">
                 <ICONS.Map className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-secondary" />
                 <input type="text" placeholder="Search transactions..." className="w-full bg-gray-50 pl-12 pr-4 py-3 rounded-xl border-none focus:ring-2 focus:ring-accent/50 text-sm font-medium" />
